import com.smach.zapmancer.domain.usecase.MarkConversationAsReadUseCase
import com.smach.zapmancer.domain.usecase.SendMessageUseCase
import com.smach.zapmancer.features.messages.state.MessagesDetailUiState
import kotlinx.coroutines.flow.collectLatest
import kotlinx.coroutines.launch

sealed class MessagesDetailEvent {
    data class OnTextChanged(val text: String) : MessagesDetailEvent()
    data object SendMessage : MessagesDetailEvent()
    data object MarkAsRead : MessagesDetailEvent()
}

class MessagesDetailViewModel(
    private val conversationId: String,
    private val getMessagesUseCase: GetMessagesUseCase,
    private val sendMessageUseCase: SendMessageUseCase,
    private val markConversationAsReadUseCase: MarkConversationAsReadUseCase,
) : BaseViewModel<MessagesDetailUiState, MessagesDetailEvent, Unit>(MessagesDetailUiState()) {

    override fun onEvent(event: MessagesDetailEvent) {
        when (event) {
            is MessagesDetailEvent.OnTextChanged -> {
                updateState { copy(typingText = event.text) }
            }

            MessagesDetailEvent.SendMessage -> sendMessage()

            MessagesDetailEvent.MarkAsRead -> markAsRead()
        }
    }

    init {
        observeMessages()
        markAsRead()
    }
    private fun observeMessages() {
        viewModelScope.launch {
            updateState { copy(isLoading = true) }
            getMessagesUseCase(conversationId).collectLatest { domainMessages ->
                updateState {
                    copy(
                        messages = domainMessages.map { domainItem ->
                            MessageItem(
                                id = domainItem.id,
                                text = domainItem.text,
                                timestamp = domainItem.timestamp,
                                isFromMe = domainItem.isFromMe,
                                status = MessageStatus.valueOf(domainItem.status.name),
                                avatarUrl = domainItem.avatarUrl,
                            )
                        },
                        isLoading = false,
                    )
                }
            }
        }
    }

    private fun sendMessage() {
        val text = uiState.value.typingText
        if (text.isBlank()) return

        viewModelScope.launch {
            updateState { copy(typingText = "") }
            sendMessageUseCase(conversationId, text)
        }
    }

    private fun markAsRead() {
        viewModelScope.launch {
            markConversationAsReadUseCase(conversationId)
        }
    }
}

package com.smach.zapmancer.features.messages.viewmodel

import androidx.lifecycle.viewModelScope
import com.smach.zapmancer.core.common.base.BaseViewModel
import com.smach.zapmancer.core.common.utils.Result
import com.smach.zapmancer.domain.model.ConversationItem
import com.smach.zapmancer.domain.usecase.GetConversationsUseCase
import com.smach.zapmancer.features.messages.state.MessagesListUiState
import kotlinx.coroutines.launch

sealed class MessagesListEvent {
    data object Refresh : MessagesListEvent()
    data class OnSearchQueryChanged(val query: String) : MessagesListEvent()
    data class OnFilterSelected(val filter: String) : MessagesListEvent()
}

class MessagesListViewModel(
    private val getConversationsUseCase: GetConversationsUseCase,
) : BaseViewModel<MessagesListUiState, MessagesListEvent, Unit>(MessagesListUiState()) {

    override fun onEvent(event: MessagesListEvent) {
        when (event) {
            MessagesListEvent.Refresh -> loadConversations()

            is MessagesListEvent.OnSearchQueryChanged -> {
                updateState { copy(searchQuery = event.query) }
            }

            is MessagesListEvent.OnFilterSelected -> {
                updateState { copy(selectedFilter = event.filter) }
            }
        }
    }

    init {
        loadConversations()
    }

    private fun loadConversations() {
        viewModelScope.launch {
            updateState { copy(isLoading = true) }
            when (val result = getConversationsUseCase()) {
                is Result.Success -> {
                    updateState {
                        copy(
                            conversations = result.data.map { domainItem ->
                                ConversationItem(
                                    id = domainItem.id,
                                    name = domainItem.name,
                                    avatarUrl = domainItem.avatarUrl,
                                    lastMessage = domainItem.lastMessage,
                                    timestamp = domainItem.timestamp,
                                    isUnread = domainItem.isUnread,
                                    isOnline = domainItem.isOnline,
                                )
                            },
                            isLoading = false,
                        )
                    }
                }

                is Result.Error -> {
                    updateState { copy(isLoading = false) }
                }
            }
        }
    }
}

package com.smach.zapmancer.features.projects.viewmodel

import androidx.lifecycle.viewModelScope
import com.smach.zapmancer.core.common.base.BaseViewModel
import com.smach.zapmancer.domain.usecase.ApplyProjectUseCase
import com.smach.zapmancer.domain.usecase.GetProjectDetailUseCase
import com.smach.zapmancer.domain.usecase.SaveProjectUseCase
import com.smach.zapmancer.features.projects.state.ProjectDetailUiState
import kotlinx.coroutines.launch

sealed interface ProjectDetailEvent {
    data object LoadProject : ProjectDetailEvent
    data object ToggleSave : ProjectDetailEvent
    data object Apply : ProjectDetailEvent
}

sealed interface ProjectDetailEffect {
    data class ShowToast(val message: String) : ProjectDetailEffect
}

class ProjectDetailViewModel(
    private val projectId: String,
    private val getProjectDetailUseCase: GetProjectDetailUseCase,
    private val saveProjectUseCase: SaveProjectUseCase,
    private val applyProjectUseCase: ApplyProjectUseCase,
) : BaseViewModel<ProjectDetailUiState, ProjectDetailEvent, ProjectDetailEffect>(
    ProjectDetailUiState(),
) {

    init {
        loadProject()
    }

    override fun onEvent(event: ProjectDetailEvent) {
        when (event) {
            ProjectDetailEvent.LoadProject -> loadProject()
            ProjectDetailEvent.ToggleSave -> toggleSave()
            ProjectDetailEvent.Apply -> apply()
        }
    }

    private fun loadProject() {
        viewModelScope.launch {
            updateState { copy(isLoading = true) }
            getProjectDetailUseCase(projectId).fold(
                onSuccess = { detail ->
                    updateState {
                        copy(
                            id = detail.id,
                            category = detail.category,
                            title = detail.title,
                            postedTime = detail.postedTime,
                            location = detail.location,
                            isPaymentVerified = detail.isPaymentVerified,
                            projectScope = detail.projectScope,
                            deliverables = detail.deliverables,
                            skills = detail.skills,
                            budgetRange = detail.budgetRange,
                            projectType = detail.projectType,
                            timeline = detail.timeline,
                            estStart = detail.estStart,
                            clientName = detail.clientName,
                            clientIndustry = detail.clientIndustry,
                            clientLocation = detail.clientLocation,
                            clientProjectsCount = detail.clientProjectsCount,
                            clientRating = detail.clientRating,
                            isSaved = detail.isSaved,
                            isClientActive = detail.isClientActive,
                            isIdentityVerified = detail.isIdentityVerified,
                            isPhoneVerified = detail.isPhoneVerified,
                            isLoading = false,
                        )
                    }
                },
                onFailure = { error ->
                    updateState { copy(isLoading = false) }
                    sendEffect(ProjectDetailEffect.ShowToast("Failed to load project details: ${error.message}"))
                },
            )
        }
    }

    private fun toggleSave() {
        val nextSavedState = !uiState.value.isSaved
        viewModelScope.launch {
            saveProjectUseCase(projectId, nextSavedState).fold(
                onSuccess = {
                    updateState { copy(isSaved = nextSavedState) }
                    sendEffect(ProjectDetailEffect.ShowToast(if (nextSavedState) "Project Saved" else "Project Unsaved"))
                },
                onFailure = { error ->
                    sendEffect(ProjectDetailEffect.ShowToast("Failed to update save state: ${error.message}"))
                },
            )
        }
    }

    private fun apply() {
        viewModelScope.launch {
            applyProjectUseCase(projectId).fold(
                onSuccess = {
                    sendEffect(ProjectDetailEffect.ShowToast("Applied successfully!"))
                },
                onFailure = { error ->
                    sendEffect(ProjectDetailEffect.ShowToast("Failed to apply: ${error.message}"))
                },
            )
        }
    }
}

