package com.smach.zapmancer.features.home.viewmodel

import androidx.lifecycle.viewModelScope
import com.smach.zapmancer.core.common.base.BaseViewModel
import com.smach.zapmancer.domain.model.UserActivity
import com.smach.zapmancer.domain.usecase.ExportActivityCsvUseCase
import com.smach.zapmancer.domain.usecase.GetHomeDashboardUseCase
import com.smach.zapmancer.features.home.state.HomeUiState
import kotlinx.coroutines.launch

sealed class HomeEvent {
    data object LoadDashboard : HomeEvent()
    data object ExportCsv : HomeEvent()
}

sealed class HomeEffect {
    data class ShowToast(val message: String) : HomeEffect()
}

class HomeViewModel(
    private val getHomeDashboardUseCase: GetHomeDashboardUseCase,
    private val exportActivityCsvUseCase: ExportActivityCsvUseCase,
    private val settingsRepository: com.smach.zapmancer.domain.repository.SettingsRepository,
) : BaseViewModel<HomeUiState, HomeEvent, HomeEffect>(HomeUiState()) {

    override fun onEvent(event: HomeEvent) {
        when (event) {
            HomeEvent.LoadDashboard -> loadDashboard()
            HomeEvent.ExportCsv -> exportCsv()
        }
    }

    init {
        loadDashboard()
        observeSettings()
    }

    private fun observeSettings() {
        viewModelScope.launch {
            settingsRepository.settingsFlow.collect { settings ->
                updateState { copy(isClientMode = settings.isClientModeEnabled) }
            }
        }
    }

    private fun loadDashboard() {
        viewModelScope.launch {
            updateState { copy(isLoading = true) }
            getHomeDashboardUseCase().fold(
                onSuccess = { dashboard ->
                    updateState {
                        copy(
                            userName = dashboard.userName,
                            totalEarnings = dashboard.earnings.amount,
                            earningsGrowth = dashboard.earnings.growthPercentage,
                            activeProjectsCount = dashboard.projectStats.activeCount,
                            totalCapacity = dashboard.projectStats.capacity,
                            systemRating = dashboard.systemRating,
                            recentActivities = dashboard.recentActivities.map { activity ->
                                UserActivity(
                                    id = activity.id,
                                    projectName = activity.projectName,
                                    category = activity.category,
                                    tag = activity.tag,
                                    status = activity.status,
                                    timestamp = activity.timestamp,
                                    monetaryValue = activity.monetaryValue,
                                )
                            },
                            isLoading = false,
                        )
                    }
                },
                onFailure = { exception ->
                    updateState { copy(isLoading = false) }
                    sendEffect(HomeEffect.ShowToast("Failed to load dashboard: ${exception.message}"))
                },
            )
        }
    }

    private fun exportCsv() {
        viewModelScope.launch {
            val activities = uiState.value.recentActivities.map {
                UserActivity(
                    id = it.id,
                    projectName = it.projectName,
                    category = it.category,
                    tag = it.category,
                    status = it.status,
                    timestamp = it.timestamp,
                    monetaryValue = it.monetaryValue,
                )
            }
            exportActivityCsvUseCase(activities).fold(
                onSuccess = { filePath ->
                    sendEffect(HomeEffect.ShowToast("CSV exported to: $filePath"))
                },
                onFailure = { exception ->
                    sendEffect(HomeEffect.ShowToast("Export failed: ${exception.message}"))
                },
            )
        }
    }
}

package com.smach.zapmancer.features.settings.viewmodel

import androidx.lifecycle.viewModelScope
import com.smach.zapmancer.core.common.base.BaseViewModel
import com.smach.zapmancer.domain.usecase.GetSettingsUseCase
import com.smach.zapmancer.domain.usecase.LogoutUseCase
import com.smach.zapmancer.domain.usecase.UpdateSettingsUseCase
import com.smach.zapmancer.features.settings.state.SettingsUiState
import kotlinx.coroutines.launch

sealed class SettingsEvent {
    data class ToggleTwoFactor(val enabled: Boolean) : SettingsEvent()
    data class ToggleDarkMode(val enabled: Boolean) : SettingsEvent()
    data class ToggleEmailNotifications(val enabled: Boolean) : SettingsEvent()
    data class ToggleClientMode(val enabled: Boolean) : SettingsEvent()
    data object Logout : SettingsEvent()
    data object LoadSettings : SettingsEvent()
}

class SettingsViewModel(
    private val getSettingsUseCase: GetSettingsUseCase,
    private val updateSettingsUseCase: UpdateSettingsUseCase,
    private val logoutUseCase: LogoutUseCase,
) : BaseViewModel<SettingsUiState, SettingsEvent, Unit>(SettingsUiState()) {

    init {
        loadSettings()
    }

    override fun onEvent(event: SettingsEvent) {
        when (event) {
            is SettingsEvent.ToggleTwoFactor -> toggleTwoFactor(event.enabled)
            is SettingsEvent.ToggleDarkMode -> toggleDarkMode(event.enabled)
            is SettingsEvent.ToggleEmailNotifications -> toggleNotifications(event.enabled)
            is SettingsEvent.ToggleClientMode -> toggleClientMode(event.enabled)
            SettingsEvent.Logout -> logout()
            SettingsEvent.LoadSettings -> loadSettings()
        }
    }

    private fun loadSettings() {
        viewModelScope.launch {
            updateState { copy(isLoading = true) }
            getSettingsUseCase().fold(
                onSuccess = { settings ->
                    updateState {
                        copy(
                            settings = settings.copy(
                                email = settings.email,
                                organization = settings.organization,
                                isTwoFactorEnabled = settings.isTwoFactorEnabled,
                                isDarkModeEnabled = settings.isDarkModeEnabled,
                                isEmailNotificationsEnabled = settings.isEmailNotificationsEnabled,
                                version = settings.version,
                                isClientModeEnabled = settings.isClientModeEnabled,
                            ),
                        )
                    }
                },
                onFailure = {
                    updateState { copy(isLoading = false) }
                },
            )
        }
    }

    private fun toggleTwoFactor(enabled: Boolean) {
        viewModelScope.launch {
            updateSettingsUseCase.updateTwoFactor(enabled).fold(
                onSuccess = {
                    updateState {
                        copy(
                            settings = settings?.copy(
                                isTwoFactorEnabled = enabled,
                            ),
                        )
                    }
                },
                onFailure = {},
            )
        }
    }

    private fun toggleDarkMode(enabled: Boolean) {
        viewModelScope.launch {
            updateSettingsUseCase.updateDarkMode(enabled).fold(
                onSuccess = {
                    updateState { copy(settings = settings?.copy(isDarkModeEnabled = enabled)) }
                },
                onFailure = {},
            )
        }
    }

    private fun toggleNotifications(enabled: Boolean) {
        viewModelScope.launch {
            updateSettingsUseCase.updateEmailNotifications(enabled).fold(
                onSuccess = {
                    updateState { copy(settings = settings?.copy(isEmailNotificationsEnabled = enabled)) }
                },
                onFailure = {},
            )
        }
    }

    private fun toggleClientMode(enabled: Boolean) {
        viewModelScope.launch {
            updateSettingsUseCase.updateClientMode(enabled).fold(
                onSuccess = {
                    updateState {
                        copy(
                            settings = settings?.copy(
                                isClientModeEnabled = enabled,
                            ),
                        )
                    }
                },
                onFailure = {},
            )
        }
    }

    private fun logout() {
        viewModelScope.launch {
            logoutUseCase()
        }
    }
}

