@Composable
fun ProjectListContent(
    state: ProjectListUiState,
    onProjectClick: (Int) -> Unit = {},
    onSearchClick: () -> Unit,
    onEvent: (ProjectListEvent) -> Unit,
    showTopBar: Boolean = true,
) {
    val content = @Composable { padding: PaddingValues ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(horizontal = 16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp),
        ) {
            if (state.isLoading) {
                item {
                    LinearProgressIndicator(
                        modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
                    )
                }
            }
            if (state.error != null) {
                item {
                    Text(
                        text = state.error,
                        color = MaterialTheme.colorScheme.error,
                        style = MaterialTheme.typography.bodyMedium,
                        modifier = Modifier.fillMaxWidth().padding(vertical = 16.dp),
                        textAlign = TextAlign.Center,
                    )
                }
            }

            val projects = if (state.category == ProjectCategory.ALL) {
                state.projects
            } else {
                state.projects.filter {
                    it.category == state.category
                }
            }

            item {
                Spacer(modifier = Modifier.height(8.dp))
                PortfolioHeader()
            }

            if (projects.isEmpty() && !state.isLoading && state.error == null) {
                item {
                    Text(
                        text = "No projects found for this category.",
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        modifier = Modifier.fillMaxWidth().padding(vertical = 32.dp),
                        textAlign = TextAlign.Center,
                    )
                }
            }

            items(projects) { project ->
                ProjectItemCard(
                    project = project,
                    onClick = { onProjectClick(project.id) },
                )
            }

            item {
                Spacer(modifier = Modifier.height(24.dp))
            }
        }
    }

    if (showTopBar) {
        Scaffold(
            topBar = {
                ZapmancerTopBar(
                    title = "Zapmancer",
                    actions = {
                        IconButton(onClick = onSearchClick) {
                            Icon(
