@Composable
fun MessagesListScreen(
    viewModel: MessagesListViewModel = koinViewModel(),
    onConversationClick: (String) -> Unit = {},
    onProfileClick: (String) -> Unit = {},
) {
    val state by viewModel.uiState.collectAsState()
    val drawerController = LocalDrawerController.current

    MessagesListContent(
        state = state,
        onEvent = viewModel::onEvent,
        onConversationClick = onConversationClick,
        onProfileClick = onProfileClick,
        onMenuClick = { drawerController.open() },
    )
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MessagesListContent(
    state: MessagesListUiState,
    onEvent: (MessagesListEvent) -> Unit,
    onConversationClick: (String) -> Unit = {},
    onProfileClick: (String) -> Unit = {},
    onMenuClick: () -> Unit = {},
    showTopBar: Boolean = true,
) {
    val content = @Composable { padding: PaddingValues ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding),
        ) {
            MessagesSearchAndFilter(
                searchQuery = state.searchQuery,
                selectedFilter = state.selectedFilter,
                onEvent = onEvent,
            )

            LazyColumn(
                modifier = Modifier
                    .fillMaxSize()
                    .background(MaterialTheme.colorScheme.surface),
            ) {
                if (state.conversations.isEmpty()) {
                    item {
                        Box(
                            modifier = Modifier
                                .fillParentMaxSize()
                                .padding(32.dp),
                            contentAlignment = Alignment.Center,
                        ) {
                            Text(
                                text = "No conversations found",
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                style = MaterialTheme.typography.bodyLarge,
                            )
                        }
                    }
                }
                items(state.conversations, key = { it.id }) { conversation ->
                    ConversationItemRow(
                        item = conversation,
                        isSelected = false,
                        onClick = { onConversationClick(conversation.id) },
                    )
                    HorizontalDivider(
                        color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.5f),
                        thickness = 1.dp,
                    )
                }
            }
        }
    }

    if (showTopBar) {
        Scaffold(
            topBar = {
                ZapmancerTopBar(
                    titleContent = {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                        ) {
                            Text(
                                "Zapmancer",
                                color = MaterialTheme.colorScheme.primary,
                                fontWeight = FontWeight.Bold,
                                fontSize = 24.sp,
                            )
                        }
                    },
                    showMenuButton = true,
                    onMenuClick = onMenuClick,
                    actions = {
                        UserAvatar(
                            onClick = { onProfileClick("me") },
                            imageUrl = null,
                            size = 32.dp,
                            shape = MaterialTheme.shapes.extraLarge,
                            borderWidth = 1.dp,
                            borderColor = MaterialTheme.colorScheme.onBackground,
                            modifier = Modifier.padding(end = 4.dp),
                        )
                    },
                    containerColor = MaterialTheme.colorScheme.surface,
                    drawBottomBorder = true,
                )
            },
            containerColor = MaterialTheme.colorScheme.background,
        ) { padding ->
            content(padding)
        }
    } else {
        content(PaddingValues(0.dp))
    }
}

@Composable
fun MessagesSearchAndFilter(
    searchQuery: String,
    selectedFilter: String,
    onEvent: (MessagesListEvent) -> Unit,
) {
    Column(
        modifier = Modifier
            .background(MaterialTheme.colorScheme.surface)
            .padding(16.dp)
            .fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(16.dp),
    ) {
        OutlinedTextField(
            value = searchQuery,
            onValueChange = { onEvent(MessagesListEvent.OnSearchQueryChanged(it)) },
            modifier = Modifier.fillMaxWidth(),
            placeholder = { Text("Search conversations...", fontSize = 14.sp) },
            leadingIcon = {
                Icon(
                    Icons.Default.Search,
                    contentDescription = null,
                    modifier = Modifier.size(20.dp),
                )
            },
            shape = RoundedCornerShape(24.dp),
            colors = OutlinedTextFieldDefaults.colors(
                focusedContainerColor = MaterialTheme.colorScheme.surfaceVariant,
                unfocusedContainerColor = MaterialTheme.colorScheme.surfaceVariant,
                focusedBorderColor = MaterialTheme.colorScheme.primary,
                unfocusedBorderColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.5f),
            ),
        )

        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            listOf("All", "Unread", "Archived").forEach { filter ->
                val isSelected = filter == selectedFilter
                Surface(
                    onClick = { onEvent(MessagesListEvent.OnFilterSelected(filter)) },
                    color = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.background,
                    contentColor = if (isSelected) Color.White else MaterialTheme.colorScheme.onSurfaceVariant,
                    shape = RoundedCornerShape(20.dp),
                    modifier = Modifier.height(32.dp),
                ) {
                    Box(
                        contentAlignment = Alignment.Center,
                        modifier = Modifier.padding(horizontal = 16.dp),
                    ) {
                        Text(filter, fontSize = 12.sp, fontWeight = FontWeight.Bold)
                    }
                }
            }
        }
    }
}

@Composable
fun ConversationItemRow(
    item: ConversationItem,
    isSelected: Boolean,
    onClick: () -> Unit,
) {
    val drawLineColor = MaterialTheme.colorScheme.primary
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onClick() }
            .background(if (isSelected) MaterialTheme.colorScheme.background else MaterialTheme.colorScheme.surface)
            .drawBehind {
                if (isSelected) {
                    val strokeWidth = 4.dp.toPx()
                    drawLine(
                        color = drawLineColor,
                        start = Offset(strokeWidth / 2, 0f),
                        end = Offset(strokeWidth / 2, size.height),
                        strokeWidth = strokeWidth,
                    )
                }
            }
            .padding(16.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        UserAvatar(
            imageUrl = item.avatarUrl,
            size = 48.dp,
            isOnline = item.isOnline,
        )

        Spacer(modifier = Modifier.width(12.dp))

        Column(modifier = Modifier.weight(1f)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Text(
                    text = item.name,
                    fontWeight = FontWeight.Bold,
                    fontSize = 16.sp,
                    color = MaterialTheme.colorScheme.onSurface,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                Text(
                    text = item.timestamp,
                    fontSize = 12.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    fontWeight = FontWeight.Medium,
                )
            }
            Text(
                text = item.lastMessage,
                fontSize = 14.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
        }

        if (item.isUnread) {
            Spacer(modifier = Modifier.width(8.dp))
            Box(
                modifier = Modifier
                    .size(10.dp)
                    .clip(CircleShape)
                    .background(MaterialTheme.colorScheme.secondary),
            )
        }
    }
}

