@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HomeScreen(
    viewModel: HomeViewModel = koinViewModel(),
    onCreateProjectClick: () -> Unit = {},
    onNavigateToProfile: () -> Unit = {},
    onExportCsvClick: () -> Unit = {},
    showSnackbar: (String) -> Unit = {},
) {
    val state by viewModel.uiState.collectAsState()
    val drawerController = LocalDrawerController.current

    LaunchedEffect(viewModel) {
        viewModel.effect.collect { effect ->
            when (effect) {
                is HomeEffect.ShowToast -> {
                    showSnackbar(effect.message)
                }
            }
        }
    }
    HomeContent(
        state = state,
        onCreateProjectClick = onCreateProjectClick,
        onExportCsvClick = onExportCsvClick,
        onMenuClick = { drawerController.open() },
        onNavigateToProfile = { onNavigateToProfile },
    )
}

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun HomeContent(
    state: HomeUiState,
    onCreateProjectClick: () -> Unit,
    onExportCsvClick: () -> Unit,
    onMenuClick: () -> Unit,
    onNavigateToProfile: () -> (() -> Unit)?,
) {
    val adaptiveInfo = currentWindowAdaptiveInfo()
    val isCompact = adaptiveInfo.windowSizeClass.windowWidthSizeClass == WindowWidthSizeClass.COMPACT

    Scaffold(
        topBar = {
            ZapmancerTopBar(
                titleContent = {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                    ) {
                        Text(
                            "Zapmancer",
                            color = MaterialTheme.colorScheme.primary,
                            style = MaterialTheme.typography.titleLarge.copy(fontWeight = FontWeight.ExtraBold),
                        )
                    }
                },
                showMenuButton = true,
                onMenuClick = {
                    onMenuClick()
                },
                actions = {
                    UserAvatar(
                        onClick = onNavigateToProfile(),
                        imageUrl = null,
                        size = 32.dp,
                        shape = MaterialTheme.shapes.extraLarge,
                        borderWidth = 1.dp,
                        borderColor = MaterialTheme.colorScheme.onBackground,
                        modifier = Modifier.padding(end = 4.dp),
                    )
                },
                containerColor = MaterialTheme.colorScheme.surface,
                drawBottomBorder = true,
            )
        },
        containerColor = MaterialTheme.colorScheme.background,
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .verticalScroll(rememberScrollState())
                .padding(padding)
                .padding(horizontal = if (isCompact) 16.dp else 24.dp),
            verticalArrangement = Arrangement.spacedBy(24.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.Bottom,
            ) {
                Column {
                    Text(
                        "Welcome back, ${state.userName}".uppercase(),
                        style = MaterialTheme.typography.labelSmall.copy(
                            fontWeight = FontWeight.Bold,
                            letterSpacing = 1.sp,
                        ),
                        color = MaterialTheme.colorScheme.primary,
                    )
                    Text(
                        "Start your Journey.",
                        style = MaterialTheme.typography.headlineLarge.copy(fontWeight = FontWeight.ExtraBold),
                        color = MaterialTheme.colorScheme.onSurface,
                    )
                }
            }

            FlowRow(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(16.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp),
            ) {
                val cardModifier = if (isCompact) Modifier.fillMaxWidth() else Modifier.weight(1f).height(160.dp)
                if (state.isClientMode) {
                    StatCard(
                        modifier = cardModifier,
                        title = "Total Spent",
                        value = "$14,800.00",
                        accentColor = MaterialTheme.colorScheme.primary,
                        icon = Icons.Default.Payments,
                        growth = "+8.2%",
                    )
                    StatCard(
                        modifier = cardModifier,
                        title = "Active Job Posts",
                        value = "3",
                        accentColor = ZapGold,
                        icon = Icons.Default.Work,
                        secondaryValue = "/ 5 capacity",
                    )
                    StatCard(
                        modifier = cardModifier,
                        title = "Proposals Received",
                        value = "12",
                        accentColor = MaterialTheme.colorScheme.secondary,
                        icon = Icons.Default.Star,
                        secondaryValue = "avg 4 bids/post",
                    )
                } else {
                    StatCard(
                        modifier = cardModifier,
                        title = "Total Earnings",
                        value = state.totalEarnings,
                        accentColor = MaterialTheme.colorScheme.primary,
                        icon = Icons.Default.Payments,
                        growth = state.earningsGrowth,
                    )
                    StatCard(
                        modifier = cardModifier,
                        title = "Current Projects",
                        value = state.activeProjectsCount.toString(),
                        accentColor = ZapGold,
                        icon = Icons.Default.Work,
                        secondaryValue = "/ ${state.totalCapacity} capacity",
                    )
                    StatCard(
                        modifier = cardModifier,
                        title = "System Rating",
                        value = state.systemRating.toString(),
                        accentColor = MaterialTheme.colorScheme.secondary,
                        icon = Icons.Default.Star,
                        isRating = true,
                    )
                }
            }
            Button(
                onClick = onCreateProjectClick,
                modifier = if (isCompact) Modifier.fillMaxWidth() else Modifier.width(300.dp),
                colors = ButtonDefaults.buttonColors(
                    containerColor = MaterialTheme.colorScheme.primary,
                ),
                shape = MaterialTheme.shapes.large,
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
                contentPadding = PaddingValues(vertical = 12.dp),
            ) {
                Text(
                    text = if (state.isClientMode) "Post a New Project" else "Browse Projects",
                    style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                )
            }

            Column(modifier = Modifier.fillMaxWidth()) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Text(
                        "Recent Activity",
                        style = MaterialTheme.typography.titleLarge,
                        fontWeight = FontWeight.Bold,
                    )
                    TextButton(onClick = onExportCsvClick) {
                        Text(
                            "Export CSV",
                            color = MaterialTheme.colorScheme.primary,
                            fontWeight = FontWeight.Bold,
                        )
                    }
                }

                if (isCompact) {
                    Column(
                        verticalArrangement = Arrangement.spacedBy(12.dp),
                    ) {
                        state.recentActivities.forEach { activity ->
                            ActivityRow(
                                activity = activity,
                                modifier = Modifier.padding(horizontal = 8.dp),
                            )
                        }
                    }
                } else {
                    FlowRow(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(16.dp),
                        verticalArrangement = Arrangement.spacedBy(16.dp),
                    ) {
                        state.recentActivities.forEach { activity ->
                            ActivityRow(
                                activity = activity,
                                modifier = Modifier.weight(1f).widthIn(min = 350.dp),
                            )
                        }
                    }
                }
            }
        }
    }
}

